harness_source:
//! Diagnostic for one fixed, ambiguous WriteWord projection, using real Domain
//! operations and the production ByteArray::summary_projection for the new side.
//! The old side is a shape-checked specialization of its original ordered loop.

use evm_abstract::{domain::{AbstractValue, Domain, NumericValue}, world::{ByteArray, ByteArraySummary}};
use evm_abstract::domain::symbolic::ByteStateKind;
use std::{hint::black_box, time::Instant};
use alloy_primitives::U256;

fn constant(value: usize) -> AbstractValue {
    AbstractValue::constant(U256::from(value))
}

fn original_union(source: &AbstractValue, domain: Domain) -> AbstractValue {
    (0..32).fold(None, |out, index| {
        let byte = domain.apply(0x1a, &[constant(index), source.clone()]);
        Some(out.map_or_else(|| byte.clone(), |old| domain.join(&old, &byte)))
    }).unwrap()
}

fn scalar(value: AbstractValue, domain: Domain) -> AbstractValue {
    let projected = domain.project(&value);
    AbstractValue::from_numeric(projected.singleton().map_or_else(|| projected.numeric().clone(), NumericValue::constant))
}

fn original_projection(input: &ByteArray, domain: Domain, expected: &ByteArraySummary) -> ByteArraySummary {
    // This specialization is valid only for the source shape proved here.
    assert!(input.is_memory());
    assert_eq!(input.len().singleton(), Some(U256::from(256)));
    assert_eq!(input.stored_bytes().len(), 0);
    let ByteStateKind::WriteWord { previous, offset, value } = input.state_root().kind() else { panic!("unexpected source"); };
    assert!(matches!(previous.kind(), ByteStateKind::Zero));
    let facts = input.symbolic_facts().collect::<std::collections::BTreeMap<_, _>>();
    let offset = facts[offset];
    assert!(offset.constants().is_none());
    assert_eq!(offset.interval().unsigned_bounds(), (U256::from(0), U256::from(224)));
    let value = facts[value];
    assert_eq!(value.interval().unsigned_bounds(), (U256::from(256), U256::from(511)));
    let numeric = Domain::from_spec(domain.spec().with_relations(evm_abstract::domain::relational::RelationLimits {
        enabled: false, ..domain.spec().relations()
    }));
    // Existing exact materialization fails on its first non-singleton byte.
    assert!(numeric.join(&constant(0), &original_union(value, numeric)).singleton().is_none());
    for _index in 0..256 {
        // Every index can overlap [offset,offset+32); no finite offset set or
        // disjoint interval proof applies. The old complete branch is this join.
        let byte = scalar(numeric.join(&constant(0), &original_union(value, numeric)), domain);
        assert_eq!(byte.numeric(), AbstractValue::unknown_byte().numeric());
    }
    let length = scalar(input.len().clone(), domain);
    assert_eq!(length.singleton(), Some(U256::from(256)));
    // All projected cells equal the unknown-byte default and are omitted. This
    // is the independently constructed canonical empty-cell bound below.
    expected.clone()
}

fn main() {
    let domain = Domain::default();
    let mut input = ByteArray::memory();
    let offset = AbstractValue::unsigned_range(U256::from(0), U256::from(224)).unwrap();
    let value = AbstractValue::unsigned_range(U256::from(256), U256::from(511)).unwrap();
    input.write_word(&offset, &value, 256, domain).unwrap();
    input.expand(&constant(0), &constant(256), 256, domain).unwrap();
    let mut arbitrary = ByteArray::memory();
    arbitrary.copy_from(&constant(0), &ByteArray::unknown(), &constant(0), &constant(256), 256, domain).unwrap();
    let expected = arbitrary.summary_projection(domain).unwrap();
    assert_eq!(original_projection(&input, domain, &expected), input.summary_projection(domain).unwrap());
    println!("{{\"case\":\"one-ambiguous-word-256-byte-memory\",\"policy\":\"library-default\",\"full_summary_equal\":true,\"old_cell_BYTE_applications\":8192,\"new_cell_BYTE_applications\":32}}");
    for round in 0..3 {
        for side in if round % 2 == 0 { ["original", "cached"] } else { ["cached", "original"] } {
            let started = Instant::now();
            let result = if side == "original" {
                original_projection(black_box(&input), domain, &expected)
            } else {
                black_box(&input).summary_projection(domain).unwrap()
            };
            let seconds = started.elapsed().as_secs_f64();
            assert_eq!(result, expected);
            println!("{{\"round\":{},\"side\":\"{}\",\"seconds\":{},\"full_summary_equal\":true}}", round + 1, side, seconds);
        }
    }
}
